#!/usr/bin/env python3
"""Summarize matched Theme planning cells with explicit censoring bounds."""

# Some portions generated by Codex

from __future__ import annotations

import argparse
import json
import math
import pathlib
import re
import statistics
import sys
from collections.abc import Iterable, Sequence


BENCHMARK_CLASS = "org.eclipse.rdf4j.sail.lmdb.benchmark.ThemeQueryPlanRunBenchmark"
ITERATION_LINE = re.compile(r"^Iteration\s+(\d+):\s*(.*)$")
MILLIS_PER_OPERATION = re.compile(r"(?:^|\s)(\d+(?:\.\d+)?)\s+ms/op\s*$")
JMH_OPERATION_TIMEOUT = re.compile(
    r"^\(benchmark timed out, interrupted \d+ times\) <failure>$", re.MULTILINE
)
COLD_LANE = "cold"
SATURATED_LANE = "saturated"


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--baseline", type=pathlib.Path, required=True)
    parser.add_argument("--candidate", type=pathlib.Path, required=True)
    parser.add_argument("--manifest", type=pathlib.Path, required=True)
    parser.add_argument("--output", type=pathlib.Path, required=True)
    args = parser.parse_args()
    for label in ("baseline", "candidate"):
        if not getattr(args, label).is_dir():
            parser.error(f"{label} campaign directory does not exist")
    if not args.manifest.is_file():
        parser.error("manifest does not exist")
    return args


def read_json(path: pathlib.Path) -> object:
    return json.loads(path.read_text(encoding="utf-8"))


def write_json(path: pathlib.Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def lane_name(method: str) -> str:
    if method == "planUncachedQuery":
        return "uncached"
    if method == "planQuery":
        return "validated-cache"
    raise ValueError(f"unsupported planning method: {method}")


def cell_id(method: str, theme: str, query: int) -> str:
    return f"{lane_name(method)}-{theme.lower()}-q{query}"


def expected_cells(manifest: dict) -> tuple[tuple[str, str, int], ...]:
    protocol = manifest["planningProtocol"]
    workload = manifest["workload"]
    return tuple(
        (method, theme, int(query))
        for method in protocol["methods"]
        for theme in workload["themes"]
        for query in workload["queryIndexes"]
    )


def finite_nonnegative(value: object) -> bool:
    return isinstance(value, (int, float)) and math.isfinite(value) and value >= 0.0


def raw_samples(metric: object, expected_count: int, expected_unit: str) -> list[float]:
    if not isinstance(metric, dict) or metric.get("scoreUnit") != expected_unit:
        raise ValueError("metric unit does not match the frozen protocol")
    raw = metric.get("rawData")
    if not isinstance(raw, list) or len(raw) != 1 or not isinstance(raw[0], list):
        raise ValueError("metric must contain exactly one fork")
    samples = raw[0]
    if len(samples) != expected_count or not all(finite_nonnegative(sample) for sample in samples):
        raise ValueError("metric samples do not match the frozen protocol")
    return [float(sample) for sample in samples]


def is_dual_lane_protocol(protocol: dict) -> bool:
    return isinstance(protocol.get("coldLane"), dict) and isinstance(
        protocol.get("saturatedLane"), dict
    )


def jmh_mode(protocol: dict) -> str | None:
    return {
        "SingleShotTime": "ss",
        "AverageTime": "avgt",
    }.get(protocol.get("mode"))


def validate_jmh_result(
    value: object,
    method: str,
    theme: str,
    query: int,
    protocol: dict,
) -> tuple[list[float], list[float]]:
    if not isinstance(value, list) or len(value) != 1 or not isinstance(value[0], dict):
        raise ValueError("JMH result must contain exactly one benchmark")
    result = value[0]
    expected_mode = jmh_mode(protocol)
    expected_measurements = int(protocol["measurementIterations"])
    params = result.get("params")
    valid = (
        expected_mode is not None
        and result.get("benchmark") == f"{BENCHMARK_CLASS}.{method}"
        and result.get("mode") == expected_mode
        and result.get("threads") == int(protocol["threads"])
        and result.get("forks") == int(protocol["forks"])
        and result.get("warmupIterations") == int(protocol["warmupIterations"])
        and result.get("measurementIterations") == expected_measurements
        and isinstance(params, dict)
        and params.get("themeName") == theme
        and params.get("z_queryIndex") == str(query)
    )
    if not valid:
        raise ValueError("JMH identity or settings do not match the frozen protocol")
    times = raw_samples(result.get("primaryMetric"), expected_measurements, "ms/op")
    secondary = result.get("secondaryMetrics")
    if not isinstance(secondary, dict):
        raise ValueError("JMH result has no secondary metrics")
    allocations = raw_samples(
        secondary.get("gc.alloc.rate.norm"), expected_measurements, "B/op"
    )
    return times, allocations


def validate_jmh_lane_result(
    value: object,
    method: str,
    theme: str,
    query: int,
    common_protocol: dict,
    lane_protocol: dict,
) -> tuple[list[float], list[float]]:
    if not isinstance(value, list) or len(value) != 1 or not isinstance(value[0], dict):
        raise ValueError("JMH result must contain exactly one benchmark")
    result = value[0]
    expected_mode = jmh_mode(lane_protocol)
    expected_measurements = int(lane_protocol["measurementIterations"])
    params = result.get("params")
    valid = (
        expected_mode is not None
        and result.get("benchmark") == f"{BENCHMARK_CLASS}.{method}"
        and result.get("mode") == expected_mode
        and result.get("threads") == int(common_protocol["threads"])
        and result.get("forks") == int(common_protocol["forks"])
        and result.get("warmupIterations") == int(lane_protocol["warmupIterations"])
        and result.get("measurementIterations") == expected_measurements
        and isinstance(params, dict)
        and params.get("themeName") == theme
        and params.get("z_queryIndex") == str(query)
    )
    if expected_mode == "avgt":
        valid = (
            valid
            and result.get("warmupTime") == f"{int(lane_protocol['warmupSeconds'])} s"
            and result.get("measurementTime")
            == f"{int(lane_protocol['measurementSeconds'])} s"
        )
    if not valid:
        raise ValueError("JMH identity or lane settings do not match the frozen protocol")
    times = raw_samples(result.get("primaryMetric"), expected_measurements, "ms/op")
    secondary = result.get("secondaryMetrics")
    if not isinstance(secondary, dict):
        raise ValueError("JMH result has no secondary metrics")
    allocations = raw_samples(
        secondary.get("gc.alloc.rate.norm"), expected_measurements, "B/op"
    )
    return times, allocations


def parse_partial_iterations(path: pathlib.Path, expected_count: int) -> dict[int, float]:
    if not path.is_file():
        return {}
    observed: dict[int, float] = {}
    pending: int | None = None
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        iteration = ITERATION_LINE.match(line)
        if iteration is not None:
            pending = int(iteration.group(1))
            tail = iteration.group(2)
        else:
            tail = line
        if pending is None or pending < 1 or pending > expected_count:
            continue
        measurement = MILLIS_PER_OPERATION.search(tail)
        if measurement is None:
            continue
        value = float(measurement.group(1))
        if math.isfinite(value) and value >= 0.0:
            observed[pending] = value
        pending = None
    return observed


def mean_bounds(
    observed: dict[int, float], indexes: Sequence[int], complete: bool
) -> dict[str, float | bool | None]:
    values = [observed[index] for index in indexes if index in observed]
    lower = sum(values) / len(indexes)
    upper = lower if complete and len(values) == len(indexes) else None
    return {"lower": lower, "upper": upper, "upperUnbounded": upper is None}


def percentile(values: Sequence[float], fraction: float) -> float:
    if not values:
        raise ValueError("cannot calculate a percentile of an empty sample")
    ordered = sorted(values)
    rank = max(1, math.ceil(fraction * len(ordered)))
    return ordered[rank - 1]


def read_status(path: pathlib.Path) -> dict | None:
    try:
        value = read_json(path)
    except (OSError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None


def jmh_operation_timed_out(
    status: dict, stdout_path: pathlib.Path, protocol: dict
) -> bool:
    timeout = protocol.get("jmhOperationTimeoutSeconds")
    command = status.get("command")
    if (
        not finite_nonnegative(timeout)
        or float(timeout) <= 0.0
        or not isinstance(command, list)
        or status.get("exitCode") != 0
        or status.get("timedOut") is not False
    ):
        return False
    try:
        command_timeout = command[command.index("-to") + 1]
    except (ValueError, IndexError):
        return False
    if command_timeout != f"{float(timeout):g}s":
        return False
    try:
        output = stdout_path.read_text(encoding="utf-8")
    except OSError:
        return False
    return JMH_OPERATION_TIMEOUT.search(output) is not None


def summarize_legacy_cell(
    directory: pathlib.Path,
    method: str,
    theme: str,
    query: int,
    protocol: dict,
) -> dict:
    identity = cell_id(method, theme, query)
    status_path = directory / f"{identity}.status.json"
    result_path = directory / f"{identity}.json"
    stdout_path = directory / f"{identity}.stdout.log"
    expected_count = int(protocol["measurementIterations"])
    cold_indexes = (int(protocol["requestColdSample"]),)
    saturated_indexes = tuple(int(index) for index in protocol["saturatedSamples"])
    issues: list[str] = []
    status = read_status(status_path)
    outcome = status.get("outcome") if status is not None else None
    observed_times: dict[int, float] = {}
    allocations: list[float] | None = None
    complete = False
    censored = False

    if status is None:
        issues.append("status-missing")
    elif outcome == "succeeded":
        if not result_path.is_file() or result_path.stat().st_size == 0:
            issues.append("jmh-missing")
        else:
            try:
                times, allocations = validate_jmh_result(
                    read_json(result_path), method, theme, query, protocol
                )
            except (OSError, json.JSONDecodeError, ValueError):
                issues.append("jmh-stale")
            else:
                observed_times = {index + 1: value for index, value in enumerate(times)}
                complete = True
    elif outcome == "timeout":
        timeout = status.get("timeoutSeconds")
        if not finite_nonnegative(timeout) or not math.isclose(
            float(timeout), float(protocol["externalCellTimeoutSeconds"])
        ):
            issues.append("status-stale")
        else:
            issues.append("timeout")
            censored = True
            observed_times = parse_partial_iterations(stdout_path, expected_count)
    elif outcome is None:
        issues.append("status-invalid")
    else:
        issues.append(f"outcome-{outcome}")

    usable_bounds = complete or censored
    observed_cold = [observed_times[index] for index in cold_indexes if index in observed_times]
    observed_saturated = [
        observed_times[index] for index in saturated_indexes if index in observed_times
    ]
    saturated_values = observed_saturated if complete else []
    cold_bounds = mean_bounds(observed_times, cold_indexes, complete) if usable_bounds else None
    saturated_bounds = (
        mean_bounds(observed_times, saturated_indexes, complete) if usable_bounds else None
    )
    saturated_allocations = (
        [allocations[index - 1] for index in saturated_indexes]
        if allocations is not None
        else None
    )
    return {
        "cellId": identity,
        "method": method,
        "theme": theme,
        "queryIndex": query,
        "status": "complete" if complete else "censored" if censored else "invalid",
        "outcome": outcome,
        "issues": issues,
        "observedColdMillis": observed_cold,
        "observedSaturatedMillis": observed_saturated,
        "coldMillisBounds": cold_bounds,
        "saturatedMeanMillisBounds": saturated_bounds,
        "saturatedP95Millis": percentile(saturated_values, 0.95) if saturated_values else None,
        "saturatedMeanAllocationBytes": (
            statistics.fmean(saturated_allocations) if saturated_allocations else None
        ),
        "rawMillis": [observed_times[index] for index in sorted(observed_times)],
        "rawAllocationBytes": allocations,
    }


def summarize_lane(
    directory: pathlib.Path,
    identity: str,
    lane: str,
    method: str,
    theme: str,
    query: int,
    common_protocol: dict,
    lane_protocol: dict,
) -> dict:
    result_path = directory / f"{identity}.{lane}.json"
    status_path = directory / f"{identity}.{lane}.status.json"
    stdout_path = directory / f"{identity}.{lane}.stdout.log"
    expected_count = int(lane_protocol["measurementIterations"])
    status = read_status(status_path)
    outcome = status.get("outcome") if status is not None else None
    issues: list[str] = []
    observed: dict[int, float] = {}
    allocations: list[float] | None = None
    complete = False
    censored = False

    if status is None:
        issues.append(f"{lane}-status-missing")
    elif outcome == "succeeded":
        if not result_path.is_file() or result_path.stat().st_size == 0:
            if jmh_operation_timed_out(status, stdout_path, common_protocol):
                issues.append(f"{lane}-jmh-operation-timeout")
                censored = True
                observed = parse_partial_iterations(stdout_path, expected_count)
            else:
                issues.append(f"{lane}-jmh-missing")
        else:
            try:
                times, allocations = validate_jmh_lane_result(
                    read_json(result_path),
                    method,
                    theme,
                    query,
                    common_protocol,
                    lane_protocol,
                )
            except (OSError, json.JSONDecodeError, ValueError):
                if jmh_operation_timed_out(status, stdout_path, common_protocol):
                    issues.append(f"{lane}-jmh-operation-timeout")
                    censored = True
                    observed = parse_partial_iterations(stdout_path, expected_count)
                else:
                    issues.append(f"{lane}-jmh-stale")
            else:
                observed = {index + 1: value for index, value in enumerate(times)}
                complete = True
    elif outcome == "timeout":
        timeout = status.get("timeoutSeconds")
        if not finite_nonnegative(timeout) or not math.isclose(
            float(timeout), float(common_protocol["externalCellTimeoutSeconds"])
        ):
            issues.append(f"{lane}-status-stale")
        else:
            issues.append(f"{lane}-timeout")
            censored = True
            observed = parse_partial_iterations(stdout_path, expected_count)
    elif outcome is None:
        issues.append(f"{lane}-status-invalid")
    else:
        issues.append(f"{lane}-outcome-{outcome}")

    indexes = tuple(range(1, expected_count + 1))
    usable_bounds = complete or censored
    values = [observed[index] for index in indexes if index in observed]
    return {
        "lane": lane,
        "status": "complete" if complete else "censored" if censored else "invalid",
        "outcome": outcome,
        "issues": issues,
        "observedMillis": values,
        "bounds": mean_bounds(observed, indexes, complete) if usable_bounds else None,
        "p95Millis": percentile(values, 0.95) if complete else None,
        "allocations": allocations,
    }


def summarize_dual_lane_cell(
    directory: pathlib.Path,
    method: str,
    theme: str,
    query: int,
    protocol: dict,
) -> dict:
    identity = cell_id(method, theme, query)
    cold = summarize_lane(
        directory,
        identity,
        COLD_LANE,
        method,
        theme,
        query,
        protocol,
        protocol["coldLane"],
    )
    saturated = summarize_lane(
        directory,
        identity,
        SATURATED_LANE,
        method,
        theme,
        query,
        protocol,
        protocol["saturatedLane"],
    )
    lane_statuses = (cold["status"], saturated["status"])
    if "invalid" in lane_statuses:
        status = "invalid"
    elif "censored" in lane_statuses:
        status = "censored"
    else:
        status = "complete"
    saturated_allocations = saturated["allocations"]
    return {
        "cellId": identity,
        "method": method,
        "theme": theme,
        "queryIndex": query,
        "status": status,
        "outcome": {
            COLD_LANE: cold["outcome"],
            SATURATED_LANE: saturated["outcome"],
        },
        "issues": cold["issues"] + saturated["issues"],
        "observedColdMillis": cold["observedMillis"],
        "observedSaturatedMillis": saturated["observedMillis"],
        "coldMillisBounds": cold["bounds"],
        "saturatedMeanMillisBounds": saturated["bounds"],
        "saturatedP95Millis": saturated["p95Millis"],
        "saturatedMeanAllocationBytes": (
            statistics.fmean(saturated_allocations)
            if saturated_allocations
            else None
        ),
        "rawMillis": cold["observedMillis"] + saturated["observedMillis"],
        "rawAllocationBytes": (
            (cold["allocations"] or []) + (saturated_allocations or [])
        ),
        "lanes": {
            COLD_LANE: cold,
            SATURATED_LANE: saturated,
        },
    }


def summarize_cell(
    directory: pathlib.Path,
    method: str,
    theme: str,
    query: int,
    protocol: dict,
) -> dict:
    if is_dual_lane_protocol(protocol):
        return summarize_dual_lane_cell(directory, method, theme, query, protocol)
    return summarize_legacy_cell(directory, method, theme, query, protocol)


def summarize_index(directory: pathlib.Path, role: str, manifest: dict) -> dict:
    path = directory / "campaign-index.json"
    issues: list[str] = []
    try:
        value = read_json(path)
    except (OSError, json.JSONDecodeError):
        value = None
    protocol = manifest["planningProtocol"]
    if not isinstance(value, dict):
        issues.append("campaign-index-missing")
        value = {}
    if is_dual_lane_protocol(protocol):
        cold = protocol["coldLane"]
        saturated = protocol["saturatedLane"]
        expected_index = {
            "formatVersion": 2,
            "coldMeasurements": int(cold["measurementIterations"]),
            "saturatedMeasurements": int(saturated["measurementIterations"]),
            "saturatedWarmupIterations": int(saturated["warmupIterations"]),
            "saturatedWarmupSeconds": int(saturated["warmupSeconds"]),
            "saturatedMeasurementSeconds": int(saturated["measurementSeconds"]),
        }
        for name, expected in expected_index.items():
            if value.get(name) != expected:
                issues.append(f"campaign-index-{name}-stale")
    elif value.get("measurements") != int(protocol["measurementIterations"]):
        issues.append("campaign-index-measurements-stale")
    timeout = value.get("externalTimeoutSeconds")
    if not finite_nonnegative(timeout) or not math.isclose(
        float(timeout), float(protocol["externalCellTimeoutSeconds"])
    ):
        issues.append("campaign-index-timeout-stale")
    jar_sha = value.get("jarSha256")
    if not isinstance(jar_sha, str) or not jar_sha:
        issues.append("campaign-index-jar-missing")
    if role == "baseline" and jar_sha != manifest["baseline"]["jmhJarSha256"]:
        issues.append("baseline-jar-mismatch")
    return {
        "path": str(path.resolve()),
        "jar": value.get("jar"),
        "jarSha256": jar_sha,
        "storeRoot": value.get("storeRoot"),
        "issues": issues,
    }


def campaign_summary(directory: pathlib.Path, role: str, manifest: dict) -> dict:
    protocol = manifest["planningProtocol"]
    cells = [
        summarize_cell(directory, method, theme, query, protocol)
        for method, theme, query in expected_cells(manifest)
    ]
    provenance = summarize_index(directory, role, manifest)
    invalid = [cell for cell in cells if cell["status"] == "invalid"]
    censored = [cell for cell in cells if cell["status"] == "censored"]
    uncached = [cell for cell in cells if cell["method"] == "planUncachedQuery"]
    cached = [cell for cell in cells if cell["method"] == "planQuery"]
    complete_uncached = [cell for cell in uncached if cell["status"] == "complete"]
    complete_cached = [cell for cell in cached if cell["status"] == "complete"]
    uncached_p95 = [float(cell["saturatedP95Millis"]) for cell in complete_uncached]
    cached_samples = [
        value
        for cell in complete_cached
        for value in cell["observedSaturatedMillis"]
    ]
    all_uncached_complete = len(complete_uncached) == len(uncached)
    all_cached_complete = len(complete_cached) == len(cached)
    return {
        "role": role,
        "directory": str(directory.resolve()),
        "status": (
            "incomplete"
            if invalid or provenance["issues"]
            else "complete-with-censoring"
            if censored
            else "complete"
        ),
        "provenance": provenance,
        "expectedCellCount": len(cells),
        "completeCellCount": len(cells) - len(invalid) - len(censored),
        "timeoutCellCount": len(censored),
        "invalidCellCount": len(invalid),
        "uncachedAllComplete": all_uncached_complete,
        "validatedCacheAllComplete": all_cached_complete,
        "uncachedCellP95Below5Fraction": (
            sum(value < 5.0 for value in uncached_p95) / len(uncached_p95)
            if all_uncached_complete and uncached_p95
            else None
        ),
        "uncachedCellP95Below0_5Fraction": (
            sum(value < 0.5 for value in uncached_p95) / len(uncached_p95)
            if all_uncached_complete and uncached_p95
            else None
        ),
        "validatedCacheHitP95Millis": (
            percentile(cached_samples, 0.95)
            if all_cached_complete and cached_samples
            else None
        ),
        "cells": cells,
    }


def sum_bounds(bounds: Iterable[dict[str, float | bool | None]]) -> dict:
    values = tuple(bounds)
    lower = sum(float(value["lower"]) for value in values)
    upper = (
        None
        if any(value["upper"] is None for value in values)
        else sum(float(value["upper"]) for value in values)
    )
    return {"lower": lower, "upper": upper, "upperUnbounded": upper is None}


def divide_bounds(numerator: dict, denominator: dict) -> dict:
    denominator_upper = denominator["upper"]
    denominator_lower = float(denominator["lower"])
    lower = (
        0.0
        if denominator_upper is None or float(denominator_upper) <= 0.0
        else float(numerator["lower"]) / float(denominator_upper)
    )
    upper = (
        None
        if numerator["upper"] is None or denominator_lower <= 0.0
        else float(numerator["upper"]) / denominator_lower
    )
    return {"lower": lower, "upper": upper, "upperUnbounded": upper is None}


def geometric_bounds(bounds: Sequence[dict]) -> dict:
    lowers = [float(value["lower"]) for value in bounds]
    lower = 0.0 if any(value <= 0.0 for value in lowers) else math.exp(
        statistics.fmean(math.log(value) for value in lowers)
    )
    if any(value["upper"] is None for value in bounds):
        upper = None
    else:
        uppers = [float(value["upper"]) for value in bounds]
        upper = 0.0 if any(value <= 0.0 for value in uppers) else math.exp(
            statistics.fmean(math.log(value) for value in uppers)
        )
    return {"lower": lower, "upper": upper, "upperUnbounded": upper is None}


def compare_campaigns(baseline: dict, candidate: dict) -> dict:
    baseline_cells = {cell["cellId"]: cell for cell in baseline["cells"]}
    candidate_cells = {cell["cellId"]: cell for cell in candidate["cells"]}
    pairs: list[dict] = []
    exact_speedups: list[float] = []
    exact_baseline_millis: list[float] = []
    exact_candidate_millis: list[float] = []
    ratio_bounds: list[dict] = []
    baseline_bounds: list[dict] = []
    candidate_bounds: list[dict] = []
    for identity, baseline_cell in baseline_cells.items():
        if baseline_cell["method"] != "planUncachedQuery":
            continue
        candidate_cell = candidate_cells.get(identity)
        baseline_time = baseline_cell["saturatedMeanMillisBounds"]
        candidate_time = (
            candidate_cell["saturatedMeanMillisBounds"]
            if candidate_cell is not None
            else None
        )
        if baseline_time is None or candidate_time is None:
            pairs.append({"cellId": identity, "status": "invalid", "speedupBounds": None})
            continue
        speedup = divide_bounds(baseline_time, candidate_time)
        ratio_bounds.append(speedup)
        baseline_bounds.append(baseline_time)
        candidate_bounds.append(candidate_time)
        exact = baseline_time["upper"] is not None and candidate_time["upper"] is not None
        if exact:
            exact_speedups.append(float(speedup["lower"]))
            exact_baseline_millis.append(float(baseline_time["lower"]))
            exact_candidate_millis.append(float(candidate_time["lower"]))
        pairs.append(
            {
                "cellId": identity,
                "status": "complete" if exact else "censored",
                "baselineSaturatedMeanMillisBounds": baseline_time,
                "candidateSaturatedMeanMillisBounds": candidate_time,
                "speedupBounds": speedup,
            }
        )
    expected = sum(
        cell["method"] == "planUncachedQuery" for cell in baseline["cells"]
    )
    complete = len(ratio_bounds) == expected
    baseline_sum = sum_bounds(baseline_bounds) if complete else None
    candidate_sum = sum_bounds(candidate_bounds) if complete else None
    fixed_speedup = (
        divide_bounds(baseline_sum, candidate_sum)
        if baseline_sum is not None and candidate_sum is not None
        else None
    )
    geometric = geometric_bounds(ratio_bounds) if complete else None
    completed_geometric = (
        math.exp(statistics.fmean(math.log(value) for value in exact_speedups))
        if exact_speedups and all(value > 0.0 for value in exact_speedups)
        else None
    )
    completed_fixed = (
        sum(exact_baseline_millis) / sum(exact_candidate_millis)
        if exact_candidate_millis and sum(exact_candidate_millis) > 0.0
        else None
    )
    return {
        "status": "complete" if complete else "incomplete",
        "uncachedExpectedPairCount": expected,
        "uncachedUsablePairCount": len(ratio_bounds),
        "uncachedExactPairCount": len(exact_speedups),
        "baselineUncachedFixedCorpusSumMillisBounds": baseline_sum,
        "candidateUncachedFixedCorpusSumMillisBounds": candidate_sum,
        "uncachedFixedCorpusSumSpeedup": fixed_speedup,
        "uncachedEqualQueryGeometricMeanSpeedup": geometric,
        "uncachedCompletedPairFixedCorpusSumSpeedup": completed_fixed,
        "uncachedCompletedPairGeometricMeanSpeedup": completed_geometric,
        "cells": pairs,
    }


def acceptance_summary(
    baseline: dict, candidate: dict, comparison: dict, manifest: dict
) -> dict:
    thresholds = manifest["acceptance"]
    fixed = comparison["uncachedFixedCorpusSumSpeedup"]
    geometric = comparison["uncachedEqualQueryGeometricMeanSpeedup"]
    evidence_present = (
        baseline["status"] != "incomplete"
        and candidate["status"] == "complete"
        and comparison["status"] == "complete"
    )
    below_five = candidate["uncachedCellP95Below5Fraction"]
    below_half = candidate["uncachedCellP95Below0_5Fraction"]
    cached_p95 = candidate["validatedCacheHitP95Millis"]
    cache_required = any(
        cell["method"] == "planQuery" for cell in candidate["cells"]
    )
    fixed_pass = (
        evidence_present
        and fixed is not None
        and float(fixed["lower"])
        >= float(thresholds["uncachedFixedCorpusSumSpeedupMinimum"])
    )
    geometric_pass = (
        evidence_present
        and geometric is not None
        and float(geometric["lower"])
        >= float(thresholds["uncachedEqualQueryGeometricMeanSpeedupMinimum"])
    )
    below_five_pass = (
        evidence_present
        and below_five is not None
        and float(below_five)
        >= float(thresholds["themeCellsBelow5MillisP95MinimumFraction"])
    )
    below_half_pass = (
        evidence_present
        and below_half is not None
        and float(below_half)
        >= float(thresholds["themeCellsBelow0_5MillisMinimumFraction"])
    )
    cache_pass = (
        None
        if not cache_required
        else evidence_present
        and cached_p95 is not None
        and float(cached_p95)
        <= float(thresholds["validatedCacheHitP95MillisMaximum"])
    )
    required_passes = [fixed_pass, geometric_pass, below_five_pass, below_half_pass]
    if cache_pass is not None:
        required_passes.append(cache_pass)
    return {
        "allRequiredEvidencePresent": evidence_present,
        "uncachedFixedCorpusSumPass": fixed_pass,
        "uncachedGeometricMeanPass": geometric_pass,
        "uncachedCellP95Below5Pass": below_five_pass,
        "uncachedCellP95Below0_5Pass": below_half_pass,
        "validatedCacheHitP95Pass": cache_pass,
        "acceptancePass": all(required_passes),
    }


def summarize_campaigns(
    baseline_directory: pathlib.Path,
    candidate_directory: pathlib.Path,
    manifest: dict,
) -> dict:
    baseline = campaign_summary(baseline_directory, "baseline", manifest)
    candidate = campaign_summary(candidate_directory, "candidate", manifest)
    comparison = compare_campaigns(baseline, candidate)
    acceptance = acceptance_summary(baseline, candidate, comparison, manifest)
    if baseline["status"] == "incomplete" or candidate["status"] == "incomplete":
        status = "incomplete"
    elif baseline["status"] == "complete-with-censoring" or candidate["status"] == "complete-with-censoring":
        status = "complete-with-censoring"
    else:
        status = "complete"
    return {
        "formatVersion": 1,
        "status": status,
        "censoringPolicy": (
            "Completed JMH samples are measurements. Missing timeout samples contribute zero only to a lower "
            "bound and leave the corresponding upper bound unbounded; no timeout is converted into a point value."
        ),
        "baseline": baseline,
        "candidate": candidate,
        "comparison": comparison,
        "acceptance": acceptance,
    }


def main() -> int:
    args = parse_args()
    manifest_value = read_json(args.manifest)
    if not isinstance(manifest_value, dict):
        raise ValueError("manifest must be a JSON object")
    summary = summarize_campaigns(args.baseline, args.candidate, manifest_value)
    write_json(args.output, summary)
    acceptance = summary["acceptance"]
    print(
        "[planning-summary] "
        f"status={summary['status']} "
        f"fixed-sum-pass={acceptance['uncachedFixedCorpusSumPass']} "
        f"geometric-pass={acceptance['uncachedGeometricMeanPass']} "
        f"absolute-p95-pass={acceptance['uncachedCellP95Below5Pass']}"
    )
    return 0 if summary["status"] != "incomplete" else 1


if __name__ == "__main__":
    sys.exit(main())
